import json
from typing import Any, Callable


class InProgressError(Exception):
    pass


class IdempotencyStore:
    """Keeps one record per key in self.records; a key whose work failed must not stay recorded."""

    def __init__(self) -> None:
        self.records: dict[str, dict[str, Any]] = {}

    def execute(self, key: str, payload: dict, work: Callable[[dict], Any]) -> Any:
        """Run work(payload) once per key and return its result.

        Same key and same payload (in any key order): the stored result. Same key, different payload: ValueError.
        Same key while the first call is still running: InProgressError.
        """
        raise NotImplementedError

